WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (403::BIGINT, 'El curso está desorganizado dentro de lo que cabe. El profe es algo pedante y sarcástico, se necesita practicar bastante en el curso y ser muy autodidacta.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2026-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'bd16d8d8c7b71e74e70204d385390e86dd225eb096d6988493ea020cc3c45a8f'::TEXT, ARRAY[1304]::BIGINT[]),
    (403::BIGINT, 'Puede ser un poco duro sobre todo si usted no tiene muy claro qué es lo que va a ir a hacer al lab. Véase los videos que le va a dejar, no lo va a dejar botado pero sí le va a decir que debería haberlo hecho. Por el resto, es súper buena nota y ayuda bastante, es muy entendido en la materia.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'c2b7e53e412ca079a7b96363b0b0d5cf2054a96586d79d2f55eb03775453f02b'::TEXT, ARRAY[3050]::BIGINT[]),
    (403::BIGINT, 'Profe bueno, logra explicar los criterios de evaluación y la materia satisfactoriamente. A veces cuesta un poco entenderlo pero eso es algo subjetivo, pero siempre se muestra abierto a resolver cualquier duda . Este curso en específico demanda mucho tiempo y trabajo en equipo. Esforzarse es clave'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2026-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'c35184a7fb07104bd44124e370fe72bc27c6583fa3069941bb543f3d9175f1fc'::TEXT, ARRAY[927, 3050]::BIGINT[]),
    (403::BIGINT, 'Buen profesor, pero el curso es difícil como el solo, las presentaciones del curso son enredadas, es mejor estudiar de los libros (sí, no existe un unico libro que abarque toda la materia). Les recomiendo salir bien en las tareas y el proyecto, porque el examen es complicado.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, '05bad9bca107c1306d0a5f488bde25462bfe7abe8529ed74b13d177abd82e3a0'::TEXT, ARRAY[1304]::BIGINT[]),
    (403::BIGINT, 'Es un curso que demanda bastante tiempo (las horas que aparecen en el expediente estudiantil no mienten) no solo por entender la materia nueva, sino repasar cursos anteriores y también la realización de tareas. Es un curso difícil, sí, pero ir a consulta ayuda bastante en general.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2025-07-10T00:00:00+00:00'::TIMESTAMPTZ, '24993780de9ffff445e3a3d85b48b84e4a7f7a7b0826de4597da8f1e295a9258'::TEXT, ARRAY[3059]::BIGINT[]),
    (403::BIGINT, 'Las clases no se aprovechan si usted no comprende la materia vista a un nivel elevado; incluso si se trata de cursos anteriores (circuitos, analógica, máquinas, etc). A partir de cierto punto, los temas se vuelven muy abstractos. Lo ideal es llevar la materia al día e investigar por cuenta propia.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2025-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'cdef6c2116751d73e588337fd702fc1eda684a687f286a5f93bfa73cab168071'::TEXT, ARRAY[3059]::BIGINT[]),
    (403::BIGINT, 'Aprovechen ahora que potencia no va a abrir nada y húyanle. Es de los peores profesores que me he topado en el TEC, nada claro, hace ejercicios casi que por obligación (uno cada 100 diapositivas) y en el examen va a matar.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, '09b5a4d603129553a42b25d8b7407c2c701e2c444967d7590d2cece3e382ed54'::TEXT, ARRAY[3059]::BIGINT[]),
    (403::BIGINT, 'Una excelente persona, se nota que le apasiona lo referente a la electriciadad... Pero no sabe dar clases. No explicó bien como hacer las entregas de bitácoras, las cuales ya son pesadas por si solas. Para los quices hay que tener todo super claro sino no hay de donde pulsear puntos. No recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Pocos exámenes']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, '01d8d7e55d66fa8bb3fbada26a320071e96489c105c0d6254714929544eb0d80'::TEXT, ARRAY[3050]::BIGINT[]),
    (403::BIGINT, 'Profe, lo amo, de verdad. Pero el pueblo lo pide, Yeiner fuera, por el bien de las generaciones de meca'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-10-28T00:00:00+00:00'::TIMESTAMPTZ, '694ac87eb547a56c4cabd6aa16906fe9b16ba48d1104f4db3046199a5532cfc0'::TEXT, ARRAY[3059]::BIGINT[]),
    (403::BIGINT, 'Increible persona pero pésimo docente. No sabe transmitir la materia y asume que el estudiante domina conceptos de cursos anteriores pero el mae se hace tanto enredo que no se entiende qué es lo que tiene que ir a repasar. Traigan de vuelta a Johana, y Yeiner porfavor retirese,total le pagan remal.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Pocos exámenes']::TEXT[], '2024-10-04T00:00:00+00:00'::TIMESTAMPTZ, '74938e1779f94f9b47550ea4b5ef874d4e5be8084787358d578edc281f228018'::TEXT, ARRAY[3059]::BIGINT[]),
    (403::BIGINT, 'Supone que el estudiante recuerda cosas del primer semestre (cuando no es así) y le vale que el 90 % del grupo no entienda.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-08-29T00:00:00+00:00'::TIMESTAMPTZ, '20ef40d187d9a9ce6235bf0cdb47afe25a16cd07874b1a82d013da1890732c7f'::TEXT, ARRAY[3059]::BIGINT[]),
    (403::BIGINT, 'El profe es muy bueno, solo que en ocasiones supone que uno sabe cosas que no. Es un toque duro en los quices y proyectos'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '0148259264dcb176e5aee5855410520265f3afeea153438ace225cea8edec61b'::TEXT, ARRAY[3050]::BIGINT[]),
    (403::BIGINT, 'El curso es prácticamente igual con ambos profes, son 4 laboratorios/proyectos y un gran proyecto final, todos se desarrollan durante varias semanas y se tiene que hacer uso del lab incluso en horas extraclase porque los proyectos son un toque pesados. Vayan a consulta y de fijo sacan buenas notas.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2024-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'de35d57eb1523eb106f827323d45c2f799060383c2a88d4824634a0cd9f94364'::TEXT, ARRAY[3060]::BIGINT[]),
    (403::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2024-03-22T00:00:00+00:00'::TIMESTAMPTZ, '9e1d72c4e6342c9169a04960351e17815cb1c5015de7cc50007174441b86673b'::TEXT, ARRAY[3066]::BIGINT[]),
    (403::BIGINT, 'Explica excelente y sabe lo que hace definitivamente. Lo incentiva a uno a realmente entender la materia a profundidad. El único problema es que a veces se le va la mano y le mete la verga a uno en el examen o proyecto, pero la retroalimentación que le hace a uno sirve para toda la carrera.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-06T00:00:00+00:00'::TIMESTAMPTZ, '085448dac40678d364d325d326350c6547666d80a1829ca309d3c6fc4858cb66'::TEXT, ARRAY[3050, 3054]::BIGINT[]),
    (403::BIGINT, 'Un profe bastante decente para lab. Hay que cuidarse de los quices. Aunque esta información solo le sirve para gente dentro de 5 años, porque el profe se va del país por ese tiempo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'c266dae127e67157e8c5cb171c3e85ee9f0e68fffde892847de00c97c0efd09f'::TEXT, ARRAY[3052]::BIGINT[]),
    (403::BIGINT, 'Este profe lo mete a uno en las exigencias que se viven a la hora de trabajar. Explica muy bien la materia y es bueno con los estudiantes. Si es duro para evaluar pero es por el bien de uno. Se fija mucho en los detalles y te obliga a pensar y practicar.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-16T00:00:00+00:00'::TIMESTAMPTZ, '51f8f415b3137007fa33bd6ed3272ae60a05e6472ae959d923635b63262eb438'::TEXT, ARRAY[3049, 3050]::BIGINT[]),
    (403::BIGINT, 'Buen profe se le entiende bien, aunque el curso en si es medio abstracto.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2018-10-12T00:00:00+00:00'::TIMESTAMPTZ, 'ad15830e3ffb200fa95bfcc5c4506bdd6f35449e5976c52f56b296b2e4e93a6d'::TEXT, ARRAY[3066]::BIGINT[]),
    (403::BIGINT, 'Es un curso bastante dificil, y el profesor hace lo posible (sin incumplir el reglamento) para que usted pase. Requiere bastante estudio y practica, se aprende mucho'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Exámenes retadores']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'ee30cd98805084c069f5a220e0ba9bb184e22fe82dfe82a6316638dc1c370444'::TEXT, ARRAY[3049]::BIGINT[]),
    (403::BIGINT, 'El curso es muy pesado, pero el profe explica muy bien y ayuda lo más que pueda si uno tiene preguntas. Los quizes y exámenes son duros pero no imposibles, la clave es practicar constantemente y no quedarse con dudas antes de una evaluación. Sí se puede pasar a la primera.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '908900cce034491400b92dd2d39501d454dbdc16a2cab271fef1734dcb4ab3b2'::TEXT, ARRAY[3049, 3050]::BIGINT[]),
    (403::BIGINT, 'Excelente profesor, sabe demasiado, es una enciclopedia andante. El curso es difícil, lo cual requiere mucho compromiso y disciplina al día. Importante llevar la materia al día y PRACTICAR!!! El profe es muy buena gente y ayuda mucho si usted tiene consultas. Lo recomiendo totalmente!'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'e9fef693df2586b1f0b02939ddc298ca3369d3b947bd220f5a24b07509fa6e03'::TEXT, ARRAY[3049]::BIGINT[]),
    (403::BIGINT, 'Tenga interés en la clase. El profe explica super bien. Es un curso donde hay que practicar bastante.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores']::TEXT[], '2018-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'e2596fda917b5d2eb03fbf855e0e60a5be4e2cb73cb88203ab0c3e9ffe69a7b6'::TEXT, ARRAY[3050]::BIGINT[]),
    (403::BIGINT, 'El Curso es difícil. Pero estudiando bien se puede pasar. CUIDADO Con el tercer examen. Recomendado'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2018-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'c394217fa66e573e3c7c8293ce613d113e5fba32d9c969c0e3c2df3171e8ee57'::TEXT, ARRAY[3049]::BIGINT[]),
    (403::BIGINT, 'Es muy bien profe y explica bien, se interesa porque los estudiantes aprendan. El curso es dificil por la materia no por el profe'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2018-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'd2c417c85da11d3292d982194571007ab6fe63ee48c1d8f098764951350c439f'::TEXT, ARRAY[3049, 3050]::BIGINT[]),
    (403::BIGINT, 'El curso es realmente difícil, sin embargo Lord Yeiner ayuda en todo lo posible'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-05-04T00:00:00+00:00'::TIMESTAMPTZ, 'ccb00ac5311a4f6188343f4cd4b48ba3281b38a129ff362ba74acf9ac716e193'::TEXT, ARRAY[3049]::BIGINT[]),
    (403::BIGINT, 'El curso en sí es duro. El profesor busca y pregunta que todos entiendan, pero si no se lleva la materia al día, nada se logra.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-07T00:00:00+00:00'::TIMESTAMPTZ, 'd0aa9ddfab936833b96c43ac7bcf701b14b510a06c53976af80828247fdf7906'::TEXT, ARRAY[3049, 3050]::BIGINT[]),
    (403::BIGINT, 'Se tiene que llevar la materia al día ya que por si sola es muy pesada. Él se esfuerza porque todos entiendan pero hay que ponerle al curso. Estudiar la materia, hacer practica y si se puede ir a tutorias. MUY difícil pero no imposible'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('15','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-08T00:00:00+00:00'::TIMESTAMPTZ, '279e3f8c38abdfc59d5a3cbfecb338feafe84d056c43cf2c0e563c68a33a20a1'::TEXT, ARRAY[3050]::BIGINT[]),
    (403::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-01T00:00:00+00:00'::TIMESTAMPTZ, '3966f35428d324770d4fa34fb5eec571cee86e162aae77a4cb903518faa0ca3d'::TEXT, ARRAY[3066]::BIGINT[]),
    (403::BIGINT, 'Es un muy buen profesor, sin embargo, si no se estudia y se lleva la materia al día, no se entenderá lo que él dé en sus clases. Es buena gente, quiere que todos pasen, pero el curso demanda mucho esfuerzo por parte del estudiante.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'd296459375a981c9ff338a626d4064869afe7451b6ae3a1e4c528ddc9b4b175f'::TEXT, ARRAY[3049, 3050]::BIGINT[]),
    (403::BIGINT, 'El curso en si es muy complicado, si no se lleva la materia al dia entre mas tiempo pase, menos posibilidades de pasar el curso. El profe intenta explicar todo, aunque ya en si la materia se ocupa mucho razonamiento, el intenta que uno entienda.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'b0bd3841ab8e75d2558d47328c1d110bb9c46790e525373a3a668f73c7dd6a53'::TEXT, ARRAY[3050]::BIGINT[]),
    (403::BIGINT, 'El curso es difícil, lo bueno es que él ayuda bastante y siempre se esmera para que todos entiendan la materia, si el estudiante no estudia se queda atrás y por eso no entiende la materia en las clases, de vez en cuando el profe explica bien pero se aprende bastante sí o sí'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-11-24T00:00:00+00:00'::TIMESTAMPTZ, '0871dbff6cca9bf6d2aa13bb15a043c388d0004f98add209c3c506c829844844'::TEXT, ARRAY[3050]::BIGINT[]),
    (403::BIGINT, 'El curso es difícil pero no es su culpa. Con Yeiner en verdad se aprende todo lo que se debería aprender en CC y CA, el curso tiene muchos contenidos entonces va rápido. Eso sí, ESTUDIE, los exámenes y quices son difíciles, pero es el TEC. Lo recomiendo, métalo con él si quiere aprender todo.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2017-10-30T00:00:00+00:00'::TIMESTAMPTZ, '53468871e789a065a739fbf826e95e6c360ff5aa48312244b4bfd451ae6b8dfb'::TEXT, ARRAY[3050]::BIGINT[]),
    (403::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '9af8ca2ab0544b6dbb43f69f7ab05f462c604f64b5018c9fb4275385654cd20c'::TEXT, ARRAY[3049, 3050]::BIGINT[]),
    (403::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-25T00:00:00+00:00'::TIMESTAMPTZ, '997363f1563cb19b029e10110af465046ee07e058f7e9ff3390caeaed047235a'::TEXT, ARRAY[3049, 3050]::BIGINT[]),
    (403::BIGINT, 'Sin comentarios'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2017-06-20T00:00:00+00:00'::TIMESTAMPTZ, '70db4494191b14629e1822173884c743303e920f41441534cec5bb9d93e6e307'::TEXT, ARRAY[3050]::BIGINT[]),
    (403::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-29T00:00:00+00:00'::TIMESTAMPTZ, '5863be8134472c39ae56cf0691dded9ff7063cc2c242ead65107e3a363c0285b'::TEXT, ARRAY[3054, 3052]::BIGINT[]),
    (403::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-01-24T00:00:00+00:00'::TIMESTAMPTZ, '4c5069d73984438b7e083f7590e667a743837588999d0b007664374f21123257'::TEXT, ARRAY[3049]::BIGINT[]),
    (403::BIGINT, 'Lo importante es ir a consulta y hacer las tareas a conciencia, explica bien pero es duro calificando.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '0f00a7de28ebe033b1e07420205dde1d59c7ed7e117b47804c02034070ff479f'::TEXT, ARRAY[3049]::BIGINT[]),
    (403::BIGINT, 'De mi experiencia como profesor, es de los profesores que jamás en la vida recomendaría; no tiene idea de cómo explicar y que el alumno tenga éxito en una materia. Les recomiendo aprender a estudiar por su propia cuenta desde antes de entrar a un curso con él. La materia es fácil, pero él no explica'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2016-12-20T00:00:00+00:00'::TIMESTAMPTZ, '3b82bd478469b33704ae192780072aac1780ae7c6edef6cd4637cdb85232538d'::TEXT, ARRAY[3049, 3050]::BIGINT[]),
    (403::BIGINT, 'Excelente profe, un poco basuriador pero siempre quiere que el estudiante aprenda de verdad, le exije lo necesario, clases super interesantes.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'cf41f18c3ce09fe9f736c7c1001f8d9df50ffad8c98b2a61ac13202cd0c9fe78'::TEXT, ARRAY[3051, 959]::BIGINT[]),
    (403::BIGINT, 'Es la peor materia que se pueda llevar. Pero está entre Vaquerano y él y diay... qué queda. Al menos es buena gente pero con cosas que solo porque él piensa que son fáciles, cree que todos lo van a ver igual y no explica y pretende que uno lo resuelva sin antes haber resuelto uno similar.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2016-12-06T00:00:00+00:00'::TIMESTAMPTZ, '416e008707aa7fa1fab0a5d1da9760ea85df59e245c417f460f265f145a2c548'::TEXT, ARRAY[3049, 3050]::BIGINT[]),
    (403::BIGINT, 'Explica bien pero lo pone a pensar bastante. No ayuda casi nada y cuesta que aclare las dudas.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-01T00:00:00+00:00'::TIMESTAMPTZ, '67c80dbdcabe49236159df10084d4d6718195f668b1be067b4cfe2644cf50483'::TEXT, ARRAY[3050]::BIGINT[]),
    (403::BIGINT, 'Exc Profe, recomendado para aprender de verdad cc y ca, el curso es duro'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2016-10-25T00:00:00+00:00'::TIMESTAMPTZ, '2799f23dd1ebc04ca411944e8383d7acac75642ab1ba480c660142f0f01ab414'::TEXT, ARRAY[3050]::BIGINT[]),
    (403::BIGINT, 'Su egocentrismo es más grande que sus ganas de enseñar. Explica muy bien y su conocimiento es amplio sin embargo necesita sentirse superior a sus alumnos. Vale la pena llevar algo con él para aprender.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'd4ff5151ab2f19f9fed5b24c3f5babcf83ef70497d10180aba0777831344d773'::TEXT, ARRAY[3050]::BIGINT[]),
    (403::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'e5feb227aa5c28d5a2cf55bceec98a445d4856bee2852fa25c28d5dc64da30d1'::TEXT, ARRAY[3050]::BIGINT[]),
    (403::BIGINT, 'Excelente profesor. Evaluaciones justas. Al ser un laboratorio se entiende mejor la teoría y obliga al estudiante a analizar todo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '1b021611dad9fc3b85b27b4190ab03d8ec8a91db4084e328137d22eb15a199ae'::TEXT, ARRAY[3054]::BIGINT[]),
    (403::BIGINT, 'Se interesa por el aprendizaje de los estudiantes aunque el curso puede llegar a ser bastante duro. Se aprende mucho'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'f40031815c2ed98f4a34ffda1a9b725698a8d3d4feaf8a8fbedb517270b350ae'::TEXT, ARRAY[3050]::BIGINT[]),
    (403::BIGINT, 'De los mejores profes, explica muy bien, pero es algo rudo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '6c4b2d5dcb2662b808b0f13b4c5e3888e580b6ccbf2d0d67cb8a4539f6bccbfb'::TEXT, ARRAY[3050, 3054]::BIGINT[]),
    (403::BIGINT, 'Para la teoría de circuitos mejor meter con Vaquerano, al final Vaquerano hace una curva y siempre da puntos en los exámenes y prácticamente todos pasan, Yeiner no da pero ni medio punto, una vez que él puso la nota no la cambia más. El estudiante aprende con el libro...'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-18T00:00:00+00:00'::TIMESTAMPTZ, '82ff213bf1b18c0d7528fe91b4085223bba4c8134dca9e769340e468104bf66a'::TEXT, ARRAY[3049]::BIGINT[]),
    (403::BIGINT, 'Es muy exigente y obliga al alumno a pensar y buscar soluciones creativas a los problemas. Es muy buen profesor.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-16T00:00:00+00:00'::TIMESTAMPTZ, '0eb795b711713a07e95377cb15b174ecc93e23ec1651d80e41b0a08437c0cf0d'::TEXT, ARRAY[3050]::BIGINT[]),
    (403::BIGINT, 'Es el mejor profesor que he tenido la dicha de conocer.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-04T00:00:00+00:00'::TIMESTAMPTZ, '16b8fd2ef4f2dec1cdda275e4995f41cd0f280c205f33521958d72d6e40b6e13'::TEXT, ARRAY[958, 960]::BIGINT[]),
    (403::BIGINT, 'El profe exige bastante y le gusta que haya que usar la lógica, aunque al final se pasa bien'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-02T00:00:00+00:00'::TIMESTAMPTZ, '3ec0d1dd6288402bb9f02e5b6055c06a454cb6b84053a593f8c312a4badf5158'::TEXT, ARRAY[958, 960]::BIGINT[]),
    (403::BIGINT, 'El profe conoce mucho, pero es demasiado exigente, siempre busca por donde bajarle puntos a uno, el trabajo que hay que hcer es execesivo para un curso de 1 crédito, eso sí, se aprende con él'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-21T00:00:00+00:00'::TIMESTAMPTZ, '6fe029449234ace58fa9272adabe6bf344927f711e0fd2187ad1e7bd6b13e539'::TEXT, ARRAY[3050]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
